// Embeds invisible provenance metadata (EXIF + XMP) identifying an output image as
// AI-generated by Stagify.ai. This is a SEPARATE layer from lib/image/stamp-disclosure.js's
// visible pixel badge: that module is the load-bearing MLS/NAR compliance mechanism and is
// untouched by this one. Metadata here is best-effort provenance — it is trivially stripped
// by a re-save, a screenshot, or most social platforms' upload pipelines — so it is applied
// unconditionally to every real output rather than gated behind the visible-badge checkbox,
// which is a UX/appearance choice this is not.
//
// sharp's withExif()/withXmp() (confirmed against this repo's pinned sharp@0.35.3 / vips@8.18.3)
// write and round-trip correctly on WebP, PNG, and JPEG alike, so one code path covers every
// call site — no format-specific branching, no new dependency.
//
// NO PARENTHESES IN ANY STRING BELOW. Confirmed by direct testing against this exact sharp
// build: its EXIF ASCII string writer truncates a tag's value at the first "(" it contains —
// e.g. "Stagify.ai (AI-generated)" is silently written as just "Stagify.ai", and everything
// from " (" onward is lost, with no error. This is a real bug in the pinned library, not a
// theoretical one — every string here has been rewritten to avoid it and to leave a paper
// trail for the next person tempted to add one back in.

/** EXIF Software / XMP CreatorTool value. */
export const STAGIFY_SOFTWARE_TAG = 'Stagify.ai';

/** EXIF Artist value — some viewers surface this instead of ImageDescription. */
export const STAGIFY_ARTIST_TAG = 'Stagify.ai, AI-generated';

/**
 * IPTC's standard code for AI/synthetic-composite imagery — what platforms' and DAM
 * tools' C2PA-adjacent provenance checks look for in Iptc4xmpExt:DigitalSourceType.
 */
export const DIGITAL_SOURCE_TYPE = 'http://cv.iptc.org/newscodes/digitalsourcetype/compositeSynthetic';

/**
 * EXIF ImageDescription / XMP dc:description per mode. Mirrors the visible badge's own
 * wording split (lib/image/stamp-disclosure.js) rather than inventing a third phrase.
 * @type {{ staged: string, edited: string }}
 */
export const DISCLOSURE_DESCRIPTIONS = Object.freeze({
  staged: 'Virtually staged with Stagify.ai; AI-generated furnishings',
  edited: 'Edited with Stagify.ai',
});

/**
 * @param {string} text
 * @returns {string}
 */
function escapeXml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/**
 * A minimal, well-formed XMP packet. Hand-built as a literal template rather than with an
 * XML-writer library — no XML dependency otherwise exists in this repo, and sharp's withXmp()
 * does no schema validation of its own, matching how stamp-disclosure.js hand-rolls its own
 * pixel buffers rather than pulling in a rasterizer.
 * @param {string} description
 * @returns {string}
 */
function buildXmpPacket(description) {
  const desc = escapeXml(description);
  // The packet's required self-identifying BOM, built from a char code rather than a
  // literal byte in source — a raw BOM in a JS file trips eslint's no-irregular-whitespace.
  const bom = String.fromCharCode(0xfeff);
  return `<?xpacket begin="${bom}" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/">
 <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
  <rdf:Description rdf:about=""
    xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/"
    xmlns:dc="http://purl.org/dc/elements/1.1/"
    xmlns:xmp="http://ns.adobe.com/xap/1.0/">
   <Iptc4xmpExt:DigitalSourceType>${DIGITAL_SOURCE_TYPE}</Iptc4xmpExt:DigitalSourceType>
   <dc:description>
    <rdf:Alt>
     <rdf:li xml:lang="x-default">${desc}</rdf:li>
    </rdf:Alt>
   </dc:description>
   <xmp:CreatorTool>${STAGIFY_SOFTWARE_TAG}</xmp:CreatorTool>
  </rdf:Description>
 </rdf:RDF>
</x:xmpmeta>
<?xpacket end="w"?>`;
}

/**
 * Queue Stagify provenance EXIF + XMP onto a sharp pipeline. Must be called before the
 * caller's own format method (.webp()/.png()/.jpeg()) — sharp applies metadata at encode
 * time, so ordering relative to resize/composite calls doesn't matter, only relative to the
 * final format call.
 *
 * @param {import('sharp').Sharp} pipeline
 * @param {{ mode: 'staged' | 'edited', mergeExif?: boolean }} options - `mode` picks the
 *   description string (see DISCLOSURE_DESCRIPTIONS). `mergeExif` (default false) chooses
 *   withExifMerge over withExif — but every call site in this codebase runs AFTER
 *   sharp(...).rotate() has already stripped the source's EXIF (see image-primitives.js and
 *   render-persistence.js), so there is nothing left to merge at any of them today; this
 *   flag exists for a future call site that runs before that strip, not for current use.
 * @returns {import('sharp').Sharp} The same pipeline, chainable.
 */
export function withDisclosureMetadata(pipeline, { mode, mergeExif = false }) {
  if (mode !== 'staged' && mode !== 'edited') {
    throw new Error(`withDisclosureMetadata: mode must be 'staged' or 'edited', got ${JSON.stringify(mode)}`);
  }
  const description = DISCLOSURE_DESCRIPTIONS[mode];
  const exif = { IFD0: { Software: STAGIFY_SOFTWARE_TAG, ImageDescription: description, Artist: STAGIFY_ARTIST_TAG } };
  const tagged = mergeExif ? pipeline.withExifMerge(exif) : pipeline.withExif(exif);
  return tagged.withXmp(buildXmpPacket(description));
}
